import os,sys,pathlib,time,threading,secrets
sys.path.insert(0,str(pathlib.Path.cwd()));sys.path.insert(0,str(pathlib.Path.cwd()/'checks'))
import task
from redis_native import NativeRedis,RedisError
assert sys.platform=='linux' and os.geteuid()!=0
print('NATIVE_LINUX_READY',flush=True)
with NativeRedis() as server:
 c=server.command;c('CONFIG','SET','busy-reply-threshold',20)
 key='counter-'+secrets.token_hex(8);c('SET',key,0);calls=[]
 def controlled(*parts):
  calls.append(parts)
  assert parts in [('SCRIPT','KILL'),('PING',)],'recovery attempted an unapproved side effect or script replay'
  return c(*parts)
 def launch(writes,duration):
  client=server.client();client.socket.settimeout(8);out=[]
  script=("redis.call('INCR',KEYS[1]);" if writes else '')+"local t=redis.call('TIME');local start=tonumber(t[1])*1000000+tonumber(t[2]);while true do local n=redis.call('TIME');if tonumber(n[1])*1000000+tonumber(n[2])-start>tonumber(ARGV[1]) then break end end;return 1"
  def run():
   try:out.append(('ok',client.command('EVAL',script,1,key,int(duration*1000000))))
   except RedisError as error:out.append(('error',str(error)))
   finally:client.close()
  thread=threading.Thread(target=run);thread.start();deadline=time.monotonic()+2
  while time.monotonic()<deadline:
   try:c('PING')
   except RedisError as error:
    if str(error).startswith('BUSY'):return thread,out
    raise
   time.sleep(.005)
  thread.join(6);raise AssertionError('expected actual native BUSY was not reproduced')
 thread,out=launch(False,4)
 try:
  print('NATIVE_READONLY_SCRIPT_BUSY',flush=True);print('STUDENT_OPERATION_ENTERED:recover',flush=True)
  assert task.recover(controlled,1)=='killed','read-only script termination was confused with natural completion'
 finally:thread.join(6)
 assert not thread.is_alive() and len(out)==1 and out[0][0]=='error' and 'killed' in out[0][1].lower()
 assert c('GET',key)=='0' and c('PING')=='PONG'
 thread,out=launch(True,2)
 try:
  try:c('SCRIPT','KILL')
  except RedisError as error:assert str(error).startswith('UNKILLABLE')
  else:raise AssertionError('write script unexpectedly killable')
  print('NATIVE_WRITTEN_SCRIPT_UNKILLABLE',flush=True)
  started=time.monotonic();result=task.recover(controlled,.05)
  assert result=='pending' and time.monotonic()-started<.6,'UNKILLABLE must remain pending within the observation budget'
  assert task.recover(controlled,3)=='completed','bounded script did not recover naturally'
 finally:thread.join(6)
 assert not thread.is_alive() and out==[('ok',1)] and c('GET',key)=='1','write was lost or script replayed'
 assert task.recover(controlled,.05)=='completed' and c('GET',key)=='1'
 assert c('CONFIG','GET','busy-reply-threshold')==['busy-reply-threshold','20'],'changing the threshold is not termination'
 for invalid in (0,-1,5,True,'1'):
  before=len(calls)
  try:task.recover(controlled,invalid)
  except ValueError:pass
  else:raise AssertionError('invalid observation budget accepted')
  assert len(calls)==before
print('NATIVE_SEMANTIC_ASSERTIONS_PASSED',flush=True)
